import{b as s,I as a,g as n,j as t}from"./chunks/framework.CrSplIeq.js";const u=JSON.parse('{"title":"Request Flow & Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),o={name:"guide/architecture.md"};function i(p,e,r,d,c,l){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="request-flow-architecture" tabindex="-1">Request Flow &amp; Architecture <a class="header-anchor" href="#request-flow-architecture" aria-label="Permalink to &quot;Request Flow &amp; Architecture&quot;">​</a></h1><h2 id="request-pipeline" tabindex="-1">Request Pipeline <a class="header-anchor" href="#request-pipeline" aria-label="Permalink to &quot;Request Pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client Request</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[security] - Security headers (CSP, HSTS, X-Frame-Options, …)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[corsMiddleware] - Origin whitelist from DB; OPTIONS → 204</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[cookieParser + /gatelin-only JSON and urlencoded parsers]</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[corsMiddleware] - Re-applied so preflight runs before route matching</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[/gatelin/health] - Liveness + DB readiness (bypasses checkRoute)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[checkRoute] - Match request against registered DB routes</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>    ├── Public login: POST /gatelin/sessions</span></span>
<span class="line"><span>    │     getUserByEmail → checkPwd → gateLoginChallenges</span></span>
<span class="line"><span>    │       ├── 202 { challengeRequired, kind, url }  (2FA / expired password)</span></span>
<span class="line"><span>    │       └── createTokens → session cache → 200</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── Public resume: POST /gatelin/sessions/resume</span></span>
<span class="line"><span>    │     redeemLoginTicket → createTokens → session cache → 200</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── Session refresh / logout: PUT|DELETE /gatelin/sessions</span></span>
<span class="line"><span>    │     JWT (+ CSRF / refresh checks) → update or archive session</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── Admin APIs: /gatelin/*</span></span>
<span class="line"><span>    │     checkRequest → entity handlers</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── Proxy (catch-all)</span></span>
<span class="line"><span>          checkRequest → additionalHeaders → forwardToService</span></span>
<span class="line"><span>          (SSE: no idle timeout; GraphQL HTTP: opaque POST/GET)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WebSocket Upgrade (HTTP server, not Express)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>corsMiddleware → checkRoute → checkRequest → additionalHeaders → socket pipe</span></span></code></pre></div><p><code>checkRequest</code> expands to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>parseBearer → decodeAccess → checkConsumer → checkAcl → applyAclConditions</span></span></code></pre></div><p>Login and resume (<code>POST /gatelin/sessions</code>, <code>POST /gatelin/sessions/resume</code>) skip <code>checkRequest</code>. Every other matched request — including refresh — goes through JWT validation. Proxy-only steps (<code>additionalHeaders</code>, <code>forwardToService</code>) run only on the catch-all proxy router. Proxy request and response bodies remain streams; only <code>/gatelin/*</code> control-plane requests are parsed into <code>req.body</code>. WebSocket upgrades are authorized on the HTTP <code>upgrade</code> event and then piped; they never enter Express.</p><p><code>gateLoginChallenges</code> reads the pwd row returned by <code>PWD_CHECK_URL</code>, enforces lockout, and may mint a challenge against the password service instead of creating a session. See <a href="./api-sessions.html#login">Sessions</a>.</p><h2 id="key-middlewares" tabindex="-1">Key Middlewares <a class="header-anchor" href="#key-middlewares" aria-label="Permalink to &quot;Key Middlewares&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Middleware</th><th>Role</th></tr></thead><tbody><tr><td><code>corsMiddleware</code></td><td>Enforces the DB-backed origin whitelist; allows <code>Authorization</code> and <code>X-CSRF-Token</code></td></tr><tr><td><code>checkRoute</code></td><td>Validates the request matches a configured route (required for login too)</td></tr><tr><td><code>checkPwd</code></td><td>Calls <code>PWD_CHECK_URL</code> and stores the public pwd row on <code>res.locals.pwdRow</code></td></tr><tr><td><code>gateLoginChallenges</code></td><td>After password OK: lockout / expiry / 2FA gating; may respond <code>202</code> with a challenge URL</td></tr><tr><td><code>redeemLoginTicket</code></td><td>Redeems a one-shot login-resume ticket and loads the user for session creation</td></tr><tr><td><code>parseBearer</code> / <code>decodeAccess</code></td><td>Extract and verify the JWT access token</td></tr><tr><td><code>checkConsumer</code></td><td>Ensures the consumer session exists in the in-memory cache</td></tr><tr><td><code>checkAcl</code></td><td>Validates route/operation/scope permissions; filters writable fields only when a body was parsed (<code>/gatelin/*</code>), and resolves field/condition metadata for proxies</td></tr><tr><td><code>applyAclConditions</code></td><td>Injects conditions into parsed <code>/gatelin/*</code> search bodies; preserves condition metadata for proxy headers</td></tr><tr><td><code>additionalHeaders</code></td><td>Adds <code>x-consumer-user-id</code> / <code>x-consumer-name</code> / <code>x-acl-conditions</code> / <code>x-acl-fields</code> before forwarding</td></tr><tr><td><code>checkCsrf</code></td><td>Double-submit CSRF check on session refresh and logout</td></tr></tbody></table><h2 id="proxy-acl-boundary" tabindex="-1">Proxy ACL boundary <a class="header-anchor" href="#proxy-acl-boundary" aria-label="Permalink to &quot;Proxy ACL boundary&quot;">​</a></h2><p>The data proxy is intentionally body-agnostic. Gatelin enforces route, method, scope, JWT, and permission checks before forwarding, but does not parse proxied JSON to enforce row or field rules. Protected upstream services enforce <code>x-acl-fields</code> and <code>x-acl-conditions</code>.</p><p>This split keeps HTTP forwarding transparent while retaining granular authorization:</p><ul><li>HTTP, GraphQL-over-HTTP, and SSE receive ACL headers on each request.</li><li>WebSocket receives ACL headers on the upgrade handshake; frames are opaque.</li><li><code>/gatelin/*</code> remains fully enforced inside Gatelin because its bodies are parsed.</li><li>Native gRPC is routed separately by Traefik/Envoy and is not handled by Gatelin.</li></ul><h2 id="production-stack" tabindex="-1">Production Stack <a class="header-anchor" href="#production-stack" aria-label="Permalink to &quot;Production Stack&quot;">​</a></h2><p>The public hostname belongs to the <strong>edge reverse proxy</strong>. Gatelin is the BFF behind it: <code>/api/*</code> is stripped to Gatelin’s routes (<code>/gatelin/*</code> control plane and proxied app paths).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Edge reverse proxy                  │</span></span>
<span class="line"><span>│            (Traefik / nginx / Envoy)             │</span></span>
<span class="line"><span>│              http://your-domain.com              │</span></span>
<span class="line"><span>└────────────┬─────────────────────┬───────────────┘</span></span>
<span class="line"><span>             │                     │</span></span>
<span class="line"><span>   ┌─────────▼─────────┐  ┌────────▼──────────┐</span></span>
<span class="line"><span>   │   Admin Panel     │  │   Gatelin (BFF)   │</span></span>
<span class="line"><span>   │  ADMIN_BASE_PATH/*│  │   /api/*          │</span></span>
<span class="line"><span>   │  (default /admin) │  │   (Node.js)       │</span></span>
<span class="line"><span>   └─────────┬─────────┘  └────────┬──────────┘</span></span>
<span class="line"><span>             │                     │</span></span>
<span class="line"><span>             └──────────┬──────────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>             ┌──────────▼──────────┐</span></span>
<span class="line"><span>             │   PostgreSQL DB     │</span></span>
<span class="line"><span>             │   (Gatelin data)    │</span></span>
<span class="line"><span>             └─────────────────────┘</span></span>
<span class="line"><span>             ┌─────────────────────┐</span></span>
<span class="line"><span>             │  Liquibase          │</span></span>
<span class="line"><span>             │  (DB Migrations)    │</span></span>
<span class="line"><span>             └─────────────────────┘</span></span></code></pre></div><h2 id="background-jobs" tabindex="-1">Background Jobs <a class="header-anchor" href="#background-jobs" aria-label="Permalink to &quot;Background Jobs&quot;">​</a></h2><p>Started with the API process:</p><ul><li><strong>Delete archived entities</strong> — daily 02:00 UTC; removes rows archived for more than 2 months</li><li><strong>Delete old history</strong> — daily 03:00 UTC; removes <code>log.history</code> rows older than 6 months</li></ul>`,19)])])}const g=s(o,[["render",i]]);export{u as __pageData,g as default};
